  if (dCalle && dNumero && dCp) {
    fields['Nombre de la calle / Name of street'] = dCalle.slice(0, 100);
    fields['Número de tu domicilio / House Number'] = dNumero.slice(0, 20);
    fields['Codigo Postal'] = dCp;
  } else {
    const falta = [];
    if (!dCalle) falta.push('calle');
    if (!dNumero) falta.push('numero');
    if (!dCpRaw) falta.push('codigo_postal');
    else if (!dCp) falta.push('codigo_postal invalido (' + dCpRaw + ')');
    descartadas.push('domicilio incompleto, falta: ' + falta.join(', '));
  }
}
// ──────────────────────────────────────────────────────────────────────────────

// ── 7/08 · Resumen del bot ────────────────────────────────────────────────────
// Es la base del informe fiscal que se le enviara al cliente, asi que se guarda
// LITERAL: no se recorta, no se normaliza y no se toca la puntuacion. Cada envio
// SUSTITUYE al anterior, porque el resumen bueno es el ultimo. Lo unico que se
// descarta es un resumen sospechosamente corto: 30 caracteres no son un resumen,
// son un saludo, y guardarlo pisaria el bueno con basura.
const resumenBruto = (body.resumen === undefined || body.resumen === null)
  ? ''
  : String(body.resumen).trim();
if (resumenBruto) {
  if (resumenBruto.length < 80) {
    descartadas.push('resumen=demasiado corto (' + resumenBruto.length + ' caracteres)');
  } else {
    fields.ResumenBot = resumenBruto.slice(0, 100000);
  }
}

// ── 10/08 · Discrepancia de fecha de alta en la SS ─────────────────────────────
// El bot ya detecta que la fecha DECLARADA no cuadra con la del documento y lo
// dice en voz alta, pero hasta hoy no quedaba escrito en ninguna parte y nadie
// del equipo lo veia (caso del 07/08: declarada 01/04/2026 contra 13/07/2026 del
// vida_laboral.pdf). Se guarda como TEXTO, no como fecha: el valor de negocio es
// justamente que NO cuadran, no cual de las dos gana. Eso lo decide una persona.
// La guarda de forma es la del bug silencioso del 03/08: un objeto pasado por
// String().trim() escribe '[object Object]' con ok:true, asi que se rechaza antes.
const discBruta = body.discrepancia_fecha_alta;
const discrepancia = (discBruta === undefined || discBruta === null)
  ? ''
  : (typeof discBruta === 'string' || typeof discBruta === 'number')
    ? String(discBruta).trim()
    : null;
if (discrepancia === null) {
  descartadas.push('discrepancia_fecha_alta=forma invalida (no es texto)');
} else if (discrepancia) {
  if (discrepancia.length > 500) {
    descartadas.push('discrepancia_fecha_alta=demasiado larga (' + discrepancia.length + ' caracteres)');
  } else {
    fields.DiscrepanciaFechaAlta = discrepancia;
  }
}

return [{ json: {
  _invalid: false,
  fields,
  _hay_fechas_descartadas: hayFechaDescartada,
  _fechas_descartadas: descartadas.join(' · '),
  _formula_userid: '{UserId} = ' + String.fromCharCode(39) + String(fields.UserId).replaceAll(String.fromCharCode(39), '') + String.fromCharCode(39)
} }];

// Preparar_Prompt · v2 · 3/08/2026
// CAMBIO: antes devolvia UN solo campo `prompt` que juntaba el turno del usuario,
// el bloque de datos conocidos y el historial. La plantilla de Langsmith tiene un
// hueco propio para el contexto, asi que ahora se devuelven DOS campos:
//   prompt   -> el turno del usuario (o la instruccion de arranque en frio) + historial
//   contexto -> el bloque DATOS QUE YA CONOCEMOS + la situacion (arranque en frio o no)
// `cold_start` se conserva por compatibilidad, aunque el systemMessage ya no lo lee:
// la situacion viaja dentro de `contexto`.

const j = $json;
const body = $('Webhook1').first().json.body || {};
const conv = $('Traer_Conversacion_intercom1').first().json || {};
const attrs = conv.custom_attributes || {};

const raw = j.last_message_content;
const cold = !raw || String(raw).trim() === '';

const dato = (v) => (v === undefined || v === null || String(v).trim() === '') ? null : String(v).trim();

// 4/08 · el atributo fecha_alta_ss_f2 llega en ISO (viene de fecha_alta_norm de F2),
// pero el RESUMEN del prompt lo escribe en DD/MM/AAAA. Se traduce aqui para que el
// agente no tenga que reformatear nada al hablar.
const fechaEs = (v) => {
  const s = dato(v);
  if (!s) return null;
  const m = s.match(/^(\d{4})-(\d{2})-(\d{2})$/);
  return m ? m[3] + '/' + m[2] + '/' + m[1] : s;
};

const conocidos = [
  ['Nombre', dato(body.nombre_apellidos)],
  ['Email', dato(body.user_email) || dato(j.user_email)],
  ['Telefono', dato(body.telefono)],
  ['Fecha de alta en la Seguridad Social', fechaEs(attrs.fecha_alta_ss_f2)],
  ['Veredicto del plazo', dato(attrs.veredicto_f2)],
  ['Fecha limite para solicitar', dato(attrs.fecha_limite_f2)]
].filter(function (par) { return par[1] !== null; })
 .map(function (par) { return '- ' + par[0] + ': ' + par[1]; })
 .join('\n');

const bloqueDatos = conocidos
  ? '--- DATOS QUE YA CONOCEMOS (no los vuelvas a preguntar) ---\n' + conocidos
  : '--- DATOS QUE YA CONOCEMOS ---\n(ninguno)';

const historial = dato(j.chat_history) || '(sin historial previo)';

const instruccionArranque = [
  '[ARRANQUE_EN_FRIO]',
  'El usuario acaba de completar la cualificacion para el regimen Beckham y todavia no ha escrito ningun mensaje.',
  'Presentate brevemente, agradece los datos que ya ha aportado y haz UNA sola pregunta para avanzar.',
  'No repitas preguntas ya respondidas en el historial ni pidas datos que ya conocemos.'
].join('\n');

// ── El turno del usuario ──────────────────────────────────────────────────────
const prompt = [
  cold ? instruccionArranque : String(raw),
  '',
  '--- HISTORIAL DE LA CONVERSACION ---',
  historial
].join('\n');

// ── El contexto, que va al systemMessage por la plantilla de Langsmith ────────
const contexto = [
  bloqueDatos,
  '',
  'Situacion: ' + (cold
    ? 'arranque en frio, el usuario todavia no ha escrito nada'
    : 'conversacion en curso')
].join('\n');

return { json: { ...j, prompt, contexto, cold_start: cold } };

return {
  json: {
    output: 'Vaya, ahora mismo no puedo continuar por un problema tecnico. Un compañero del equipo lo revisara y te escribira en breve. Disculpa las molestias.'
  }
};

const input = $input.first().json;
const body = input.body || {};
const query = input.query || {};
const raw = (body.user_id !== undefined && body.user_id !== null) ? body.user_id : query.user_id;
const userId = (raw === undefined || raw === null) ? '' : String(raw).trim();
if (!userId) { return [{ json: { _invalid: true, error: 'user_id_missing' } }]; }
const q = String.fromCharCode(39);
const clean = userId.replaceAll(q, '');
const formula = '{UserId} = ' + q + clean + q;
return [{ json: { _invalid: false, user_id: userId, formula: formula } }];

const userId = $('Validar user_id').first().json.user_id;

// ── 10/08 · WP-205b · el lector detecta el UserId duplicado ────────────────────
// Buscar Expediente iba con limit:1, asi que la API truncaba y era IMPOSIBLE
// enterarse de que habia dos filas. Con limit:2 se puede contar. El lector sigue
// devolviendo UNA (la primera) porque el agente necesita algo con lo que seguir
// la conversacion, pero ahora lo dice en la respuesta. Sin esto pasaba lo peor:
// el agente leia de la fila A, el escritor escribia en la B, y el bot volvia a
// preguntar datos que el cliente ya habia dado.
const encontradas = $input.all()
  .map(i => i.json || {})
  .filter(x => typeof x.id === 'string' && x.id.startsWith('rec'));
const nFilas = encontradas.length;
const raw = encontradas[0] || {};

const f = raw.fields ? raw.fields : raw;
const recordId = raw.id || null;
if (!recordId) { return [{ json: { ok: true, existe: false, duplicado: false, filas: 0, user_id: userId, record_id: null, expediente: null } }]; }
function txt(v) { if (v === undefined || v === null || v === '') { return null; } if (typeof v === 'object' && v.name !== undefined) { return String(v.name); } return String(v); }
function bool(v) { return v === true; }
function fecha(v) { if (v === undefined || v === null || v === '') { return null; } return String(v).slice(0, 10); }
const expediente = {
  UserId: txt(f.UserId),
  email: txt(f.email),
  nombre: txt(f['Nombre empleado']),
  apellidos: txt(f['Apellidos empleado']),
  nif: txt(f.NIF),
  telefono: txt(f.NumeroTelefono),
  fecha_nacimiento: fecha(f.FechaNacimiento),
  tipo_via: txt(f['Tipo de vía / Type of road']),
  calle: txt(f['Nombre de la calle / Name of street']),
  numero: txt(f['Número de tu domicilio / House Number']),
  planta: txt(f.Planta),
  puerta: txt(f.Puerta),
  codigo_postal: txt(f['Codigo Postal']),
  alta_ss: bool(f.alta_ss),
  fecha_alta_ss: fecha(f.fecha_alta_ss),
  Descarte: txt(f.Descarte),
  lead_potencial: bool(f.lead_potencial),
  fecha_prevista_alta: fecha(f.fecha_prevista_alta),
  fecha_limite_plazo: fecha(f.fecha_limite_plazo),
  Status: txt(f.Status),
  intercom_conversation_id: txt(f.intercom_conversation_id)
};
return [{ json: { ok: true, existe: true, duplicado: nFilas > 1, filas: nFilas, user_id: userId, record_id: recordId, expediente: expediente } }];

// ── 7/08 · Decide Status y Empresa leyendo lo que ya hay en Airtable ───────────
// SIEMPRE .first(), NUNCA .item: este nodo acaba de meterse en medio de la cadena
// y un .item aqui rompe el paired item. Asi se cayo el bot el 6/08 a las 17:20.
const base = $('Validar y Normalizar').first().json;
const fields = Object.assign({}, base.fields);

// ── 10/08 · WP-205b · guarda de UNICIDAD de UserId ─────────────────────────────
// Leer_Status_Actual va con alwaysOutputData:true, asi que cuando NO encuentra
// nada emite un item VACIO. Por eso no se puede contar $input.all().length a
// secas: hay que contar solo los items que traen un record id de Airtable.
// count==0 -> cliente nuevo, el upsert lo crea (comportamiento de siempre)
// count==1 -> actualiza esa fila (comportamiento de siempre)
// count>1  -> AMBIGUO: no se escribe nada y se avisa. Hasta hoy se cogia la
//             primera EN SILENCIO y el upsert actualizaba una cualquiera, asi
//             que el bot podia LEER de una fila y ESCRIBIR en la otra.
const encontradas = $input.all()
  .map(i => i.json || {})
  .filter(f => typeof f.id === 'string' && f.id.startsWith('rec'));
const nFilas = encontradas.length;

const leido = encontradas[0] || $input.first().json || {};

// Si la LECTURA fallo, no se toca ni Status ni Empresa. Preferimos dejarlos como
// esten antes que decidir a ciegas: una fila vacia y una lectura fallida se
// parecen mucho, y confundirlas pisaria el trabajo de una persona.
const lecturaFallo = leido.error !== undefined;

// Airtable devuelve los singleSelect a veces como cadena y a veces como objeto
// con name, y a veces planos y a veces dentro de fields. Se aceptan las cuatro
// combinaciones, igual que hace 'Formatear Respuesta Expediente' desde el 27/07.
const crudo = leido.fields ? leido.fields : leido;
function leerSelect(v) {
  if (v === undefined || v === null || v === '') return '';
  if (typeof v === 'object' && v.name !== undefined) return String(v.name);
  return String(v);
}
const statusActual = leerSelect(crudo.Status);
const empresaActual = leerSelect(crudo.Empresa);

// ── 10/08 · WP-205b slice B · HUELLA de la escritura (idempotencia) ────────────
// Se calcula sobre 'base.fields', o sea sobre lo que MANDA el bot, y NO sobre los
// fields finales con Status y Empresa ya decididos. El motivo importa: tras la
// primera escritura el Status ya ha avanzado, asi que un reintento calcularia un
// Status distinto, la huella cambiaria y el dedup NO DISPARARIA NUNCA.
// Y NO se usa user_id|punto|conversation_id como decia el PRD, porque el bot
// guarda de forma INCREMENTAL: en una conversacion normal manda esos tres valores
// IDENTICOS muchas veces con campos distintos, y esa huella habria descartado el
// segundo y el tercer guardado, perdiendo el NIF y el telefono.
// Las claves se ORDENAN antes de serializar: sin eso, el mismo contenido en otro
// orden daria otra huella.
function canonico(o) {
  const claves = Object.keys(o).sort();
  return JSON.stringify(claves.map(function (k) { return [k, o[k]]; }));
}
function huella(txt) {
  let h1 = 0x811c9dc5;
  let h2 = 0x01000193;
  for (let i = 0; i < txt.length; i++) {
    const c = txt.charCodeAt(i);
    h1 = ((h1 ^ c) * 0x01000193) >>> 0;
    h2 = (((h2 + c) >>> 0) * 0x85ebca6b) >>> 0;
    h2 = (h2 ^ (h2 >>> 13)) >>> 0;
  }
  // Dos hashes distintos MAS la longitud: una colision aqui saltaria una
  // escritura legitima, asi que se paga el doble para que sea improbable.
  return ('0000000' + h1.toString(16)).slice(-8)
       + ('0000000' + h2.toString(16)).slice(-8)
       + '-' + txt.length;
}
const idemKey = huella(canonico(base.fields || {}));
const idemActual = leerSelect(crudo.last_idem_key);

// Solo se deduplica con UNA fila: con cero no hay nada que comparar, y con dos
// manda la guarda de unicidad, que es mas grave.
const dedup = !lecturaFallo && nFilas === 1 && idemActual !== '' && idemActual === idemKey;

fields.last_idem_key = idemKey;

// ── STATUS: el bot solo AVANZA, nunca retrocede ────────────────────────────────
// Los nombres van COPIADOS LITERAL de Airtable, con sus acentos y con el 10 sin
// espacio tras el punto. Un nombre mal escrito aqui, con typecast:true, CREARIA
// UNA OPCION NUEVA en la columna en vez de fallar.
const ORDEN = {
  '1. Interesado': 1,
  '2. Pendiente llamada TD': 2,
  '3. Pte hacer informe': 3,
  '4. Informe enviado': 4,
  '5. Pte formulario usuario': 5,
  '6. Pte hacer TD': 6,
  '7. Pte confirmación usuario': 7,
  '8. Confirmado': 8,
  '9. Finalizado': 9,
  '10.Pendiente resolución': 10,
  '11. Concedido': 11,
  '12. Descartado': 12
};

// ── 11/08 · WP-238 · El Status depende de COMO se cierra, no solo de que quiera ─
// ANTES: AplicaBeckham===true daba SIEMPRE '2. Pendiente llamada TD'. Un
// expediente completo se quedaba clavado en 'pendiente llamada' aunque no
// hubiera ninguna llamada que hacer. Evidencia: conversacion 215475438827585
// del 11/08, 5 de 5 documentos, MotivoCierre='Expediente completo', Status en 2.
//
// Se mira PRIMERO lo que llega en esta llamada y, si no viene, lo que ya hay en
// la fila: el bot guarda de forma INCREMENTAL y el motivo puede haberse escrito
// en un turno anterior. leerSelect() ya sabe leer las cuatro formas en que
// Airtable devuelve un singleSelect, asi que se reutiliza y no se duplica.
//
// OJO CON LA GRAFIA: estos dos nombres van copiados LITERAL de Airtable, igual
// que los de ORDEN. Con typecast:true un nombre mal escrito NO FALLA: crea una
// opcion nueva en la columna.
const motivoCierre = leerSelect(fields.MotivoCierre) || leerSelect(crudo.MotivoCierre);

let propuesto;
if (fields.Descarte) {
  propuesto = '12. Descartado';
} else if (motivoCierre === 'Expediente completo') {
  // No queda nada pendiente del cliente: lo siguiente lo hace TaxDown.
  // Cuando WP-236 genere el informe de verdad, este caso pasa a
  // '4. Informe enviado' y este comentario hay que borrarlo.
  propuesto = '3. Pte hacer informe';
} else if (motivoCierre === 'Llamada agendada' || fields.AplicaBeckham === true) {
  propuesto = '2. Pendiente llamada TD';
} else {
  propuesto = '1. Interesado';
}
const nActual = ORDEN[statusActual] || 0;
const nPropuesto = ORDEN[propuesto] || 0;
let escribirStatus = !lecturaFallo && nPropuesto > nActual;

// El descarte solo vale al principio. Si el equipo ya esta trabajando el caso
// (3 o mas), un descarte del bot seria un error suyo, no un dato nuevo.
if (propuesto === '12. Descartado' && nActual > 2) escribirStatus = false;

if (escribirStatus) fields.Status = propuesto;

// ── EMPRESA: TaxDown SOLO si la celda esta vacia ────────────────────────────────
// La columna tiene otras cuatro opciones (Globant y Factorial, interno y externo)
// y las pone una PERSONA a mano. Si el bot escribiera TaxDown en cada guardado,
// borraria ese trabajo en CADA turno de la conversacion. Solo se rellena el hueco.
// OJO CON LA GRAFIA: es 'TaxDown' con D MAYUSCULA.
const escribirEmpresa = !lecturaFallo && !empresaActual;
if (escribirEmpresa) fields.Empresa = 'TaxDown';

// Se devuelve la MISMA FORMA que Validar y Normalizar para que los 51 mapeos del
// nodo de Airtable sigan funcionando sin tocar ni uno.
return [{ json: {
  _invalid: false,
  fields,
  _hay_fechas_descartadas: base._hay_fechas_descartadas,
  _fechas_descartadas: base._fechas_descartadas,
  _lectura_fallo: lecturaFallo,
  _status_actual: statusActual,
  _status_propuesto: propuesto,
  _status_escrito: escribirStatus ? propuesto : null,
  _empresa_actual: empresaActual,
  _empresa_escrita: escribirEmpresa ? 'TaxDown' : null,
  _n_filas: nFilas,
  _multi_match: !lecturaFallo && nFilas > 1,
  _user_id: String(fields.UserId || ''),
  _idem_key: idemKey,
  _idem_actual: idemActual,
  _dedup: dedup
} }];
